SELECT s.s_store_id, CASE WHEN s.s_closed_date_sk IS NULL THEN 'Open' ELSE 'Closed' END AS store_status, d.d_year, d.d_month_seq, s.s_floor_space / NULLIF(s.s_number_employees, 0) AS floor_space_per_employee, s.s_gmt_offset * 60 AS gmt_offset_minutes, CONCAT(s.s_city, ', ', s.s_state) AS city_state, date_format(d.d_date, '%Y-%m-%d') AS formatted_date, s.s_tax_percentage * 100 AS tax_percentage_basis_points, d.d_day_name || ' - ' || d.d_quarter_name AS day_quarter, CASE WHEN d.d_holiday = 'Y' THEN 1 ELSE 0 END AS is_holiday, s.s_number_employees + s.s_floor_space AS employee_plus_floor, s.s_number_employees * s.s_tax_percentage AS employee_tax_product FROM store s JOIN date_dim d ON s.s_closed_date_sk = d.d_date_sk WHERE d.d_year = 100
